<?php
final class SubstituteShift
{
    private static $done=false;
    private static function normDate($v){$s=trim((string)$v);if($s==='')return null;$s=str_replace(['/','.'],'-',$s);if(!preg_match('/^(\d{4})-(\d{1,2})-(\d{1,2})$/',$s,$m))return null;$y=(int)$m[1];$mo=(int)$m[2];$d=(int)$m[3];if($y<1300||$y>1600||$mo<1||$mo>12||$d<1||$d>31)return null;return sprintf('%04d-%02d-%02d',$y,$mo,$d);}
    private static function ready(){Db::run("CREATE TABLE IF NOT EXISTS substitute_assignments (id INT AUTO_INCREMENT PRIMARY KEY,substitute_user_id INT NOT NULL,request_id INT NOT NULL,absent_user_id INT NOT NULL,from_date VARCHAR(10) NOT NULL,to_date VARCHAR(10) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_sub_user(substitute_user_id),INDEX idx_sub_dates(from_date,to_date),INDEX idx_sub_request(request_id),INDEX idx_sub_absent(absent_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
    public static function reconcile(){if(self::$done)return;self::$done=true;try{self::ready();Db::run("UPDATE substitute_assignments SET from_date=REPLACE(TRIM(from_date),'/','-'),to_date=REPLACE(TRIM(to_date),'/','-') WHERE from_date LIKE '%/%' OR to_date LIKE '%/%'");$rows=Db::all("SELECT id,user_id,substitute_user_id,status,from_jdate,to_jdate,the_date FROM requests WHERE substitute_user_id IS NOT NULL AND CAST(substitute_user_id AS UNSIGNED)>0 AND status IN ('approved','rejected','cancelled','canceled')");foreach($rows as $r){$rid=(int)$r['id'];$sid=(int)$r['substitute_user_id'];$aid=(int)$r['user_id'];$from=self::normDate($r['from_jdate']?:($r['the_date']??''));$to=self::normDate($r['to_jdate']?:($r['the_date']??'')?:($r['from_jdate']??''));if($rid<=0||$sid<=0||$aid<=0||!$from||!$to)continue;if($from>$to){$x=$from;$from=$to;$to=$x;}if($r['status']==='approved'){$ex=Db::one("SELECT id FROM substitute_assignments WHERE request_id=? AND status='active' ORDER BY id DESC LIMIT 1",[$rid]);if($ex)Db::run("UPDATE substitute_assignments SET substitute_user_id=?,absent_user_id=?,from_date=?,to_date=? WHERE id=?",[$sid,$aid,$from,$to,(int)$ex['id']]);else Db::run("INSERT INTO substitute_assignments (substitute_user_id,request_id,absent_user_id,from_date,to_date,status) VALUES (?,?,?,?,?,'active')",[$sid,$rid,$aid,$from,$to]);}else Db::run("UPDATE substitute_assignments SET status='inactive' WHERE request_id=? AND status='active'",[$rid]);}Db::run("UPDATE substitute_assignments sa LEFT JOIN requests r ON r.id=sa.request_id SET sa.status='inactive' WHERE sa.status='active' AND (r.id IS NULL OR r.status<>'approved' OR r.substitute_user_id IS NULL OR CAST(r.substitute_user_id AS UNSIGNED)<>sa.substitute_user_id OR r.user_id<>sa.absent_user_id)");}catch(Throwable $e){error_log('substitute shift reconciliation: '.$e->getMessage());}}
}
